mapper.select:
SELECT *
  FROM SM_STMT
 WHERE SETTLE_DT BETWEEN #{fromDt} AND #{toDt}

   AND MCHT_ID = #{mchtId}

 ORDER BY SETTLE_DT, MCHT_ID, PAY_METHOD

SELECT *
  FROM SM_STMT_TID
 WHERE SETTLE_DT = #{settleDt}

   AND MCHT_ID = #{mchtId}

 ORDER BY STMT_TID_SEQ

SELECT *
  FROM SM_STMT
 WHERE MCHT_ID = #{mchtId}
   AND STMT_ST_CD = #{stmtStCd}
 ORDER BY PAYOUT_DT DESC, SETTLE_DT, PAY_METHOD
 LIMIT 60
